                        cnt += 1
            region_counts.append(cnt)

    # Determine which regions to fill (Max Count)
    max_count = max(region_counts) if region_counts else 0

    # Construct output grid
    # Initialize with background
    out = [[bg_val for _ in range(cols)] for _ in range(rows)]

    # Place separators
    for r in range(rows):
        for c in range(cols):
